  function header(phase,title,description,actionLabel,action){return '<section class="page-heading module-page-heading"><div><p class="eyebrow">SECUREBUSINESS · '+phase+'</p><h1>'+title+'</h1><p class="page-subtitle">'+description+'</p></div><div class="module-heading-actions"><span class="demo-note"><i></i> Datos de demostración · sin conexión al backend</span>'+(actionLabel?'<button class="btn btn-primary app-primary-button" type="button" data-account-action="'+action+'"><span class="button-plus">＋</span><span>'+actionLabel+'</span></button>':"")+'</div></section>';}
