  function formField(label,name,value,options={}){const required=options.required!==false,type=options.type||"text",placeholder=options.placeholder||"",min=options.min||"";return '<div class="'+(options.col||"col-md-6")+'"><div class="field-wrap"><label>'+label+(required?' <span class="required-mark">*</span>':"")+'</label>'+(options.textarea?'<textarea class="form-control" name="'+name+'" '+(required?"required":"")+(min?' minlength="'+min+'"':"")+' placeholder="'+esc(placeholder)+'">'+esc(value||"")+'</textarea>':'<input class="form-control" name="'+name+'" type="'+type+'" value="'+esc(value||"")+'" '+(required?"required":"")+(min?' minlength="'+min+'"':"")+(options.autocomplete?' autocomplete="'+options.autocomplete+'"':"")+' placeholder="'+esc(placeholder)+'">')+'<div class="invalid-feedback"></div></div></div>';}
  function formSelect(label,name,options,value,required=true){return '<div class="col-md-6"><div class="field-wrap"><label>'+label+(required?' <span class="required-mark">*</span>':"")+'</label><select class="form-select" name="'+name+'" '+(required?"required":"")+'>'+selectOptions(options,value,required?"Selecciona una opción":"Sin asignar")+'</select><div class="invalid-feedback"></div></div></div>';}
